#include <string>

class Solution {
public:
    long long minOperations(std::string s, std::string target) {
        long long ans = 0;
        int n = s.size();
        for (int i = 0; i < n; ++i) {
            int diff = (target[i] - s[i] + 26) % 26;
            ans += diff;
        }
        return ans;
    }
};

class Solution {
    public long minOperations(String s, String target) {
        long ans = 0;
        int n = s.length();
        for (int i = 0; i < n; i++) {
            int diff = (target.charAt(i) - s.charAt(i) + 26) % 26;
            ans += diff;
        }
        return ans;
    }
}

var minOperations = function(s, target) {
    let ans = 0;
    const n = s.length;
    for (let i = 0; i < n; i++) {
        const diff = (target.charCodeAt(i) - s.charCodeAt(i) + 26) % 26;
        ans += diff;
    }
    return ans;
